select app_id, tenant_id, app_name, status, token_status, sdk_version, remark, create_by, create_time, update_by, update_time
from agentsec_agent_app

    and tenant_id = #{tenantId}
    and app_name like concat('%', #{appName}, '%')
    and status = #{status}

order by create_time desc

